export const LP_MONITOR_DEFAULT_RULES_CONFIG = Object.freeze({
  poolImbalanceEnabled: true,
  poolImbalanceRatioLimit: 7,
  noCompetitiveYieldEnabled: true,
  noCompetitiveYieldMultiplier: 1.5,
  rebalanceRiskEnabled: true,
  rebalanceRiskBoundaryRatio: 0.05,
  highTvlShareEnabled: true,
  highTvlShareThreshold: 0.3,
});

export const LP_MONITOR_RULE_SCHEMA = Object.freeze([
  Object.freeze({
    id: 'pool_value_ratio_imbalance',
    scope: 'pool',
    label: 'Pool imbalance',
    enabledKey: 'poolImbalanceEnabled',
    valueKey: 'poolImbalanceRatioLimit',
    input: Object.freeze({
      min: 1.01,
      step: 0.1,
      fallback: LP_MONITOR_DEFAULT_RULES_CONFIG.poolImbalanceRatioLimit,
    }),
    cli: Object.freeze({
      enabledArg: 'enable-rule4',
      valueArg: 'rule4-ratio-limit',
    }),
  }),
  Object.freeze({
    id: 'no_competitive_yield',
    scope: 'position',
    label: 'No competitive yield',
    enabledKey: 'noCompetitiveYieldEnabled',
    valueKey: 'noCompetitiveYieldMultiplier',
    input: Object.freeze({
      min: 1,
      step: 0.1,
      fallback: LP_MONITOR_DEFAULT_RULES_CONFIG.noCompetitiveYieldMultiplier,
    }),
    cli: Object.freeze({
      enabledArg: 'enable-rule1',
      valueArg: 'rule1-multiplier',
    }),
  }),
  Object.freeze({
    id: 'near_boundary_rebalance',
    scope: 'position',
    label: 'Need rebalance',
    enabledKey: 'rebalanceRiskEnabled',
    valueKey: 'rebalanceRiskBoundaryRatio',
    input: Object.freeze({
      min: 0.001,
      max: 1,
      step: 0.01,
      fallback: LP_MONITOR_DEFAULT_RULES_CONFIG.rebalanceRiskBoundaryRatio,
    }),
    cli: Object.freeze({
      enabledArg: 'enable-rule2',
      valueArg: 'rule2-boundary-ratio',
    }),
  }),
  Object.freeze({
    id: 'high_single_position_tvl_share',
    scope: 'position',
    label: 'High single-position TVL share',
    enabledKey: 'highTvlShareEnabled',
    valueKey: 'highTvlShareThreshold',
    input: Object.freeze({
      min: 0.01,
      max: 1,
      step: 0.01,
      fallback: LP_MONITOR_DEFAULT_RULES_CONFIG.highTvlShareThreshold,
    }),
    cli: Object.freeze({
      enabledArg: 'enable-rule3',
      valueArg: 'rule3-threshold',
    }),
  }),
]);

export function encodeLpMonitorPoolOverrides(value) {
  return encodeURIComponent(JSON.stringify(Array.isArray(value) ? value : []));
}

export function decodeLpMonitorPoolOverrides(value) {
  const text = String(value || '').trim();
  if (!text) return [];
  try {
    const parsed = JSON.parse(decodeURIComponent(text));
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function encodeLpMonitorTargetOverrides(value) {
  return encodeURIComponent(JSON.stringify(Array.isArray(value) ? value : []));
}

export function decodeLpMonitorTargetOverrides(value) {
  const text = String(value || '').trim();
  if (!text) return [];
  try {
    const parsed = JSON.parse(decodeURIComponent(text));
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function toNumber(value, fallback) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function toBoolean(value, fallback = false) {
  if (typeof value === 'boolean') return value;
  const text = String(value ?? '').trim().toLowerCase();
  if (!text) return fallback;
  if (['1', 'true', 'yes', 'on'].includes(text)) return true;
  if (['0', 'false', 'no', 'off'].includes(text)) return false;
  return fallback;
}

function normalizeRuleNumericValue(definition, value, fallback) {
  const min = definition.input.min;
  const max = definition.input.max;
  const normalized = toNumber(value, fallback);
  const lowerBounded = Math.max(min, normalized);
  return typeof max === 'number' ? Math.min(max, lowerBounded) : lowerBounded;
}

export function createDefaultLpMonitorRulesConfig() {
  return {
    ...LP_MONITOR_DEFAULT_RULES_CONFIG,
  };
}

export function normalizeLpMonitorRulesConfig(
  input,
  fallback = createDefaultLpMonitorRulesConfig()
) {
  const source = input || {};
  const next = {
    ...fallback,
  };

  for (const definition of LP_MONITOR_RULE_SCHEMA) {
    next[definition.enabledKey] = toBoolean(source[definition.enabledKey], fallback[definition.enabledKey]);
    next[definition.valueKey] = normalizeRuleNumericValue(
      definition,
      source[definition.valueKey],
      fallback[definition.valueKey]
    );
  }

  return next;
}

export function buildLpMonitorCliArgs(params) {
  const normalizedOwners = Array.from(
    new Set(
      (Array.isArray(params.owners) ? params.owners : [params.owner])
        .map((item) => String(item || '').trim().toLowerCase())
        .filter(Boolean)
    )
  );
  const scopeOwner = String(params.scopeOwner || params.owner || normalizedOwners[0] || '')
    .trim()
    .toLowerCase();

  if (normalizedOwners.length === 0) {
    throw new Error('buildLpMonitorCliArgs requires at least one owner');
  }

  const args = [`--owners=${normalizedOwners.join(',')}`];
  if (scopeOwner) {
    args.push(`--scope-owner=${scopeOwner}`);
  }

  for (const definition of LP_MONITOR_RULE_SCHEMA) {
    args.push(`--${definition.cli.enabledArg}=${params.rules[definition.enabledKey] ? 'true' : 'false'}`);
    args.push(`--${definition.cli.valueArg}=${params.rules[definition.valueKey]}`);
  }

  if (Array.isArray(params.selectedChains) && params.selectedChains.length > 0) {
    args.push(`--chains=${params.selectedChains.join(',')}`);
  }
  if (Array.isArray(params.selectedDexNames) && params.selectedDexNames.length > 0) {
    args.push(`--dexes=${params.selectedDexNames.join(',')}`);
  }
  if (Array.isArray(params.poolOverrides) && params.poolOverrides.length > 0) {
    args.push(`--pool-overrides=${encodeLpMonitorPoolOverrides(params.poolOverrides)}`);
  }
  if (Array.isArray(params.targetOverrides) && params.targetOverrides.length > 0) {
    args.push(`--target-overrides=${encodeLpMonitorTargetOverrides(params.targetOverrides)}`);
  }

  return args;
}
